 "El reparto": "La distribution",
 "<div style=\"font-family:'Playfair Display', serif;font-size:23px;color:#e07a3f;font-weight:700\">Bruno</div><div style=\"font-style:italic;color:#d8c3a0\">el posadero</div><div style=\"margin-top:8px\">Pablo Ríos</div>": "<div style=\"font-family:'Playfair Display', serif;font-size:23px;color:#e07a3f;font-weight:700\">Bruno</div><div style=\"font-style:italic;color:#d8c3a0\">l'aubergiste</div><div style=\"margin-top:8px\">Pablo Ríos</div>",
 "<div style=\"font-family:'Playfair Display', serif;font-size:23px;color:#9d7cff;font-weight:700\">Alma</div><div style=\"font-style:italic;color:#d8c3a0\">la viajera</div><div style=\"margin-top:8px\">Lucía Pons</div>": "<div style=\"font-family:'Playfair Display', serif;font-size:23px;color:#9d7cff;font-weight:700\">Alma</div><div style=\"font-style:italic;color:#d8c3a0\">la voyageuse</div><div style=\"margin-top:8px\">Lucía Pons</div>",
